/// <summary>
/// Business event triggered when a transfer order is received.
/// </summary>
[BusinessEvents(classStr(AAXTransferOrderReceivedBusinessEventContract), 'TransferOrderReceivedBusinessEventName', 'TransferOrderReceivedBusinessEventDescription', ModuleAxapta::Inventory)]
public final class AAXTransferOrderReceivedBusinessEvent extends BusinessEventsBase
{
    private InventTransferTable inventTransferTable;

}

Method.Source:
/// <summary>
/// Gets or sets the source InventTransferTable for building the event contract.
/// </summary>
private InventTransferTable parmInventTransferTable(InventTransferTable _inventTransferTable = inventTransferTable)
{
    inventTransferTable = _inventTransferTable;

    return inventTransferTable;
}

/// <summary>
/// Creates a new <c>AAXTransferOrderReceivedBusinessEvent</c> instance from the specified <c>InventTransferTable</c> record.
/// </summary>
/// <param name="_inventTransferTable">The source InventTransferTable record.</param>
/// <returns>A new instance of <c>AAXTransferOrderReceivedBusinessEvent</c>.</returns>
public static AAXTransferOrderReceivedBusinessEvent newFromInventTransferTable(InventTransferTable _inventTransferTable)
{
    AAXTransferOrderReceivedBusinessEvent businessEvent = new AAXTransferOrderReceivedBusinessEvent();
    businessEvent.parmInventTransferTable(_inventTransferTable);

    return businessEvent;
}

/// <summary>
/// Private constructor. Use static factory methods to create instances.
/// </summary>
private void new()
{
}

/// <summary>
/// Builds the data contract for this business event.
/// </summary>
/// <returns>The populated <c>AAXTransferOrderReceivedBusinessEventContract</c>.</returns>
[Wrappable(true), Replaceable(true)]
public BusinessEventsContract buildContract()
{
    return AAXTransferOrderReceivedBusinessEventContract::newFromInventTransferTable(inventTransferTable);
}
